// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
  random,
} from '../remotionShim';
// ------------------------------------------------------------------
// FONTS
// ------------------------------------------------------------------
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// ------------------------------------------------------------------
// SCHEMA
// ------------------------------------------------------------------


export type RubberStampProps = Record<string, any>;

// ------------------------------------------------------------------
// COMPONENT
// ------------------------------------------------------------------
const RubberStamp: React.FC<RubberStampProps> = ({
  backgroundColor = "#fdfbf7",
  transparentBackground = false,
  durationInSeconds = 5,
  stampText = "NO VIEWS",
  inkColor = "#b71c1c",
  fontSize = 180,
  stampBodyColor = "#1a1a1a",
  stampHandleColor = "#5d4037",
  impactFrame = 20,
  recoilSpeed = 1.2,
}) => {
  // Load specialized font for the distressed look
  useFontLoader(["Rubik Dirt"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // 1. Dynamic Sizing for Perspective Correction
  // We switch from a side-view stamp to a top-down view to match the "paper" (screen) perspective.
  // The stamp body needs to be large enough to obscure the text.
  const charWidthApprox = fontSize * 0.65;
  const estimatedTextWidth = stampText.length * charWidthApprox;
  const stampWidth = Math.max(estimatedTextWidth + (fontSize * 1.5), width * 0.35); 
  const stampHeight = fontSize * 1.8;

  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // 2. Animation Stages
  
  // Stage A: The Approach (Z-axis Slam + Y-axis slide)
  // We simulate the stamp coming from the user's hand towards the screen (paper)
  const slamProgress = interpolate(
    frame,
    [0, impactFrame],
    [0, 1],
    {
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.7, 0.0, 1, 0.5), // Aggressive acceleration
    }
  );

  // Z-Axis: Starts large (close to camera), ends at 1 (on paper)
  const scale = interpolate(slamProgress, [0, 1], [3.5, 1]);
  
  // Y-Axis: Moves from slightly above center to center (simulating arm swing)
  const yOffset = interpolate(slamProgress, [0, 1], [-height * 0.25, 0]);

  // Shadow Physics (To sell the depth)
  // As object approaches paper (scale -> 1), shadow gets sharper and closer
  const shadowBlur = interpolate(slamProgress, [0, 1], [60, 0]);
  const shadowOpacity = interpolate(slamProgress, [0, 1], [0.2, 0.6]);
  const shadowOffset = interpolate(slamProgress, [0, 1], [150, 0]); // Moves under the object

  // Stage B: The Impact (Shake)
  const isHit = frame >= impactFrame;
  const shakeDuration = 8;
  const shakeProgress = interpolate(
    frame,
    [impactFrame, impactFrame + shakeDuration],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const shakeX = (random(frame) - 0.5) * 30 * shakeProgress;
  const shakeY = (random(frame + 100) - 0.5) * 30 * shakeProgress;

  // Stage C: Recoil (Lift off)
  const holdFrames = 15; // Hold down for a moment
  const recoilStart = impactFrame + holdFrames;
  
  const recoilSpring = spring({
    frame: frame - recoilStart,
    fps,
    config: {
      damping: 15,
      stiffness: 60,
      mass: 1.5 / recoilSpeed,
    },
  });

  // When recoiling, we lift UP (Scale Increase) and Away (Fade)
  let finalScale = scale;
  let finalOpacity = 1;
  let finalY = yOffset;

  if (frame > recoilStart) {
      // Lift straight up towards camera
      const recoilScale = interpolate(recoilSpring, [0, 1], [1, 1.4]);
      finalScale = recoilScale;
      
      // Move slightly up in Y to clear frame naturally
      const recoilMove = interpolate(recoilSpring, [0, 1], [0, -100]);
      finalY = recoilMove;
      
      // Fade out the tool (it moves out of focus/frame)
      finalOpacity = interpolate(frame, [recoilStart, recoilStart + 15], [1, 0], { extrapolateRight: "clamp" });
  }

  // 3. Ink / Text Appearance
  // Text is strictly hidden until impact.
  // The stamp body (Top View) covers the area, so we can reveal text instantly on impact.
  const textOpacity = frame >= impactFrame ? 1 : 0;
  
  // Ink Spread Effect
  const inkScale = spring({
    frame: frame - impactFrame,
    fps,
    config: { damping: 10, stiffness: 200 },
  });
  
  const finalInkScale = interpolate(inkScale, [0, 1], [0.85, 1], { extrapolateRight: "clamp" });
  
  // Random Rotation for organic feel
  const rotation = -2 + (random("rot") * 4);

  // 4. Styles

  const containerStyle: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    backgroundColor: finalBgColor,
    overflow: "hidden",
  };

  // The Stamp Tool Container (Moves in Z and Y)
  const stampContainerStyle: React.CSSProperties = {
    position: "absolute",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    transform: `translateY(${finalY + shakeY}px) translateX(${shakeX}px) scale(${finalScale}) rotate(${rotation}deg)`,
    opacity: finalOpacity,
    zIndex: 20, // Must be above text
    transformOrigin: "center center",
  };

  // Top-Down View: The Block (Body)
  const stampBlockStyle: React.CSSProperties = {
    width: stampWidth,
    height: stampHeight,
    backgroundColor: stampBodyColor,
    borderRadius: "12px",
    boxShadow: `inset 0 0 40px rgba(0,0,0,0.6), 0 ${shadowOffset}px ${shadowBlur}px rgba(0,0,0,${shadowOpacity})`,
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    position: "relative",
    border: "1px solid rgba(255,255,255,0.1)",
  };

  // Top-Down View: The Handle (Knob)
  const knobSize = Math.min(stampHeight * 0.7, 140);
  const stampHandleStyle: React.CSSProperties = {
    width: knobSize,
    height: knobSize,
    borderRadius: "50%",
    backgroundColor: stampHandleColor,
    background: `radial-gradient(circle at 30% 30%, ${stampHandleColor} 0%, #2a1e1a 100%)`, // Fake 3D lighting
    boxShadow: "0 10px 20px rgba(0,0,0,0.4), inset 2px 2px 10px rgba(255,255,255,0.1)",
    zIndex: 2,
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  };

  // Decorative Screw on top of handle
  const screwStyle: React.CSSProperties = {
      width: knobSize * 0.2,
      height: knobSize * 0.2,
      borderRadius: "50%",
      backgroundColor: "#111",
      boxShadow: "inset 0 0 2px rgba(0,0,0,0.8)"
  }

  // The Ink Mark (Text on Paper)
  const markStyle: React.CSSProperties = {
    fontFamily: "Rubik Dirt, sans-serif",
    fontSize: fontSize,
    color: inkColor,
    opacity: textOpacity,
    transform: `scale(${finalInkScale}) rotate(${rotation}deg)`, 
    zIndex: 5, // Below the stamp tool
    textAlign: "center",
    lineHeight: 1,
    mixBlendMode: transparentBackground ? "normal" : "multiply", 
    filter: "contrast(1.3)",
    position: "absolute",
  };

  return (
    <AbsoluteFill style={containerStyle}>
      {/* Texture Filter */}
      <svg width="0" height="0" style={{ position: "absolute" }}>
        <filter id="ink-texture">
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.8"
            numOctaves="3"
            result="noise"
          />
          <feDisplacementMap
            in="SourceGraphic"
            in2="noise"
            scale="4"
          />
        </filter>
      </svg>

      {/* The MARK (Text on Paper) */}
      <div style={markStyle}>
        {stampText}
      </div>

      {/* The STAMP TOOL (Physical Object - Top Down View) */}
      <div style={stampContainerStyle}>
          <div style={stampBlockStyle}>
             {/* Wood grain detail (CSS) */}
             <div style={{
                 position: 'absolute', width: '90%', height: '80%', 
                 border: '2px dashed rgba(0,0,0,0.1)', borderRadius: '8px' 
             }} />
             
             {/* Handle */}
             <div style={stampHandleStyle}>
                <div style={screwStyle} />
             </div>
          </div>
      </div>

    </AbsoluteFill>
  );
};

export default RubberStamp;